package dev.cxo.filmpack.core

import java.io.File
import java.nio.ByteBuffer
import java.nio.ByteOrder

/** Golden samples are captured native sensor-only output, not generated by this implementation. */
fun main(args: Array<String>) {
    require(args.isNotEmpty()) { "Expected native sensor fixture files" }
    var components = 0
    for (path in args) {
        val bytes = ByteBuffer.wrap(File(path).readBytes()).order(ByteOrder.LITTLE_ENDIAN)
        val magic = ByteArray(8).also { bytes.get(it) }
        val extended = magic.contentEquals("CXORAW02".toByteArray())
        check(extended || magic.contentEquals("CXORAW01".toByteArray()))
        val count = bytes.int
        check(count > 0 && count < 1_000_000)
        val tolerance = if (extended) bytes.int else 0
        val stage = if (extended) bytes.int else 0
        check(stage in 0..1 && tolerance in 0..if (stage == 0) 1 else 4)
        val ev = bytes.float
        val highlight = bytes.float
        val matrix = FloatArray(9) { bytes.float }
        val source = ShortArray(count * 3) { bytes.short }
        val expected = ShortArray(count * 3) { bytes.short }
        check(!bytes.hasRemaining())
        val transform = RawSensorToWorking(matrix, ev, highlight)
        val output = ShortArray(source.size)
        transform.renderQ15(source, output)
        if (stage == 1) RawOriginalTone.renderQ15(output, output)
        val mismatch = output.indices.filter { output[it] != expected[it] }
        val maxError = output.indices.maxOf { kotlin.math.abs(output[it].toInt() - expected[it].toInt()) }
        check(maxError <= tolerance) {
            "$path: ${mismatch.size}/${source.size} differ, max=$maxError Q15; first=${mismatch.first()} " +
                "actual=${output[mismatch.first()]} expected=${expected[mismatch.first()]}"
        }
        val inPlace = source.copyOf()
        transform.renderQ15(inPlace, inPlace)
        if (stage == 1) RawOriginalTone.renderQ15(inPlace, inPlace)
        check(inPlace.contentEquals(output))
        check(runCatching { transform.renderQ15(shortArrayOf(-1, 0, 0), ShortArray(3)) }.isFailure)
        components += output.size
        println("${File(path).name}: ${source.size - mismatch.size}/${source.size} native components exact, max error=$maxError Q15, stage=$stage; in-place exact")
    }
    println("RAW verification: $components native components checked; film and output ICC excluded")
}
